<template><el-dialog v-model="visible" title="建立加工批次" width="min(650px,94vw)" :close-on-click-modal="false" :close-on-press-escape="!busy&&!uncertain" :show-close="!busy&&!uncertain"><el-form ref="batchForm" :model="form" :rules="rules" scroll-to-error label-width="120px" :disabled="busy||uncertain||loading"><el-form-item label="工厂"><el-select v-model="factoryId" :disabled="!admin" fit-input-width @change="factoryChanged"><el-option v-for="o in factories" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item label="生产工单" prop="workOrderId" :rules="[requiredRule('生产工单',true,true),...([])]"><el-select v-model="form.workOrderId" fit-input-width @change="orderChanged"><el-option v-for="o in orders" :key="o.id" :label="o.name" :value="o.id"/></el-select></el-form-item><el-form-item :label="rawTask?'原料明细':'产品明细'" prop="itemId" :rules="[requiredRule('产品明细',true,true),...([])]"><el-select v-model="form.itemId" fit-input-width @change="form.processId=''"> <el-option v-for="(o,i) in items" :key="o.id" :label="(o.materialSnapshot??o.snapshot)?.name+' '+(i+1)+(rawTask?' / '+o.plannedInputWeight+' g':'（'+o.quantity+'件）')" :value="o.id"/></el-select></el-form-item><el-form-item label="工序" prop="processId" :rules="[requiredRule('工序',true,true),...([])]"><el-select v-model="form.processId" fit-input-width><el-option v-for="o in processes" :key="o.processId" :label="o.processName" :value="o.processId"/></el-select></el-form-item><p v-if="rawTask">原料加工按实测净重结算。</p><p v-else-if="weightStage">本工序按重量管理，产出按实测净重结算；无需填写加工件数。</p><el-form-item v-else label="加工数量" prop="plannedQuantity" :rules="[requiredRule('加工数量',true,false),...([])]"><el-input v-model="form.plannedQuantity" @input="v=>quantityInput=String(v)" inputmode="numeric"/></el-form-item></el-form><p v-if="refreshFailed" role="status">更新检查失败，当前资料可能过期。</p><el-alert v-if="error" :title="error" type="warning" :closable="false"/><el-button v-if="needsReload&&!uncertain" @click="recheck">重新核对候选</el-button><template #footer><el-button v-if="uncertain" type="primary" :loading="busy" @click="retryRequest">重试原请求</el-button><el-button :disabled="busy||uncertain||loading" @click="visible=false">取消</el-button><el-button v-if="actionPermission.has('metal:process-batch:add')" type="primary" :loading="busy" :disabled="needsReload||uncertain||loading" @click="save">确认</el-button></template></el-dialog></template>
<script setup lang="ts">
import {requiredRule} from '@/utils/input-validation'
import type {FormInstance} from 'element-plus'
import {integerError,fieldRule,applyFieldErrors} from '@/utils/input-validation'
import { useActionPermission } from '@/composables/useActionPermission'
const actionPermission=useActionPermission()
import {createUUID} from '@/utils/uuid'
import {getToken} from '@/utils/auth'
import {useInventoryRefresh} from '@/composables/useInventoryRefresh'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import{ref,reactive,computed,watch,onBeforeUnmount}from'vue';import{ElMessage}from'element-plus';import useUserStore from '@/store/modules/user';import{warehouseOptions,warehouseSave,type Row}from'@/api/metal/warehouse';import{orderDetail}from'@/api/metal/work-order';
const user=useUserStore()
const emit=defineEmits(['saved']),visible=ref(false),busy=ref(false),factoryId=ref(''),factories=ref<Row[]>([]),orders=ref<Row[]>([]),items=ref<Row[]>([]),form=reactive<Row>({}),admin=computed(()=>String(user.id)==='1'),processes=computed(()=>items.value.find(o=>o.id===form.itemId)?.plans??[]);
const rawTask=ref(false)
const weightStage=computed(()=>processes.value.find((p:Row)=>p.processId===form.processId)?.measurementMode==='WEIGHT');
const batchForm=ref<FormInstance>(),quantityInput=ref<string>()
const choose=(label:string)=>[fieldRule(v=>v?'':'请选择'+label,'change')]
const rules={workOrderId:choose('生产工单'),itemId:choose('产品明细'),processId:choose('工序'),plannedQuantity:[fieldRule(v=>rawTask.value||weightStage.value?'':integerError(quantityInput.value??v,'加工数量'),['blur','change'])]}
const identity=()=>JSON.stringify([user.token,String(user.id),[...user.permissions].sort()]);let openedIdentity=''
const sessionCurrent=()=>user.sessionReady&&!!user.token&&user.token===getToken()&&openedIdentity===identity()
let epoch=0,dependency=0,disposed=false,ordersBaseline='',orderBaseline=''
const loading=ref(false),needsReload=ref(false),uncertain=ref(false),error=ref('');let pendingRequest:Row|undefined
const stamp=(v:Row)=>JSON.stringify([v.version,v.status,v.taskType,v.items]);
async function factoryChanged(){if(uncertain.value)return;const round=epoch,ticket=++dependency,factory=factoryId.value,valid=()=>!disposed&&sessionCurrent()&&round===epoch&&ticket===dependency&&factory===factoryId.value;form.workOrderId='';form.itemId='';form.processId='';items.value=[];orders.value=[];loading.value=true;try{const r=await warehouseOptions('work-orders',factory,undefined,valid);if(valid()){orders.value=r.data;ordersBaseline=JSON.stringify(r.data)}}catch(e:any){if(valid())error.value=e.message}finally{if(valid())loading.value=false}}
async function orderChanged(){if(uncertain.value)return;const round=epoch,ticket=++dependency,order=form.workOrderId,valid=()=>!disposed&&sessionCurrent()&&round===epoch&&ticket===dependency&&order===form.workOrderId;form.itemId='';form.processId='';items.value=[];loading.value=true;try{const r=await orderDetail(order,valid);if(valid()){items.value=r.data.items;orderBaseline=stamp(r.data);rawTask.value=r.data.taskType==='RAW_PROCESSING'}}catch(e:any){if(valid())error.value=e.message}finally{if(valid())loading.value=false}}
async function open(factory?:string){if(busy.value||uncertain.value||!user.sessionReady||!user.token||user.token!==getToken())return;openedIdentity=identity();needsReload.value=false;error.value='';const round=++epoch,valid=()=>!disposed&&sessionCurrent()&&round===epoch&&actionPermission.has('metal:process-batch:add');Object.assign(form,{requestId:createUUID(),workOrderId:'',itemId:'',processId:'',plannedQuantity:1});quantityInput.value=undefined;batchForm.value?.clearValidate();loading.value=true;try{const r=await warehouseOptions('factories',undefined,undefined,valid);if(!valid())return;factories.value=r.data;factoryId.value=factory||(!admin.value?factories.value[0]?.id:'')||'';if(factoryId.value)await factoryChanged();else{orders.value=[];items.value=[]}if(valid())visible.value=true}catch(e:any){if(valid())error.value=e.message}finally{if(valid())loading.value=false}}

async function save(){if(!sessionCurrent()||busy.value||uncertain.value||needsReload.value||!visible.value||!actionPermission.has('metal:process-batch:add'))return;const round=epoch;if(!await batchForm.value?.validate().catch(()=>false)||disposed||round!==epoch||!visible.value||!sessionCurrent()||!actionPermission.has('metal:process-batch:add'))return;form.plannedQuantity=rawTask.value?0:weightStage.value?1:Number(form.plannedQuantity);pendingRequest=JSON.parse(JSON.stringify(form));await retryRequest()}
async function retryRequest(){if(!sessionCurrent()||!visible.value||!actionPermission.has('metal:process-batch:add')||busy.value||!pendingRequest)return;const round=epoch,attempt=pendingRequest,valid=()=>!disposed&&sessionCurrent()&&round===epoch&&visible.value&&actionPermission.has('metal:process-batch:add');busy.value=true;try{await warehouseSave('process-batch',attempt,valid);if(!valid()||pendingRequest!==attempt)return;uncertain.value=false;pendingRequest=undefined;visible.value=false;ElMessage.success('加工批次已建立');emit('saved')}catch(e:any){if(valid()){uncertain.value=typeof e?.code!=='number';if(!uncertain.value)pendingRequest=undefined;error.value=uncertain.value?'提交结果未知，请重试原请求确认结果；当前输入已保留。':e.message||'建立批次失败';applyFieldErrors(batchForm.value,e)}}finally{if(valid())busy.value=false}}
async function recheck(){if(busy.value||uncertain.value)return;const round=epoch,factory=factoryId.value,id=form.workOrderId;loading.value=true;try{const r=await warehouseOptions('work-orders',factory,undefined,()=>!disposed&&sessionCurrent()&&round===epoch);if(disposed||!sessionCurrent()||round!==epoch)return;orders.value=r.data;ordersBaseline=JSON.stringify(r.data);if(id){const detail=await orderDetail(id,()=>!disposed&&sessionCurrent()&&round===epoch);if(disposed||!sessionCurrent()||round!==epoch)return;items.value=detail.data.items;orderBaseline=stamp(detail.data)}needsReload.value=false;error.value=''}catch(e:any){if(!disposed&&sessionCurrent()&&round===epoch)error.value=e.message}finally{if(!disposed&&sessionCurrent()&&round===epoch)loading.value=false}}
const {failed:refreshFailed}=useInventoryRefresh(async()=>{},computed(()=>true),{allowed:()=>visible.value&&actionPermission.has('metal:process-batch:add'),reset:()=>{epoch++;dependency++;visible.value=false;busy.value=false;loading.value=false;uncertain.value=false;pendingRequest=undefined}},{paused:computed(()=>busy.value||loading.value||uncertain.value),probe:async ctx=>{const round=epoch,factory=factoryId.value,id=form.workOrderId,valid=()=>ctx.isCurrent()&&!disposed&&sessionCurrent()&&round===epoch&&visible.value&&!busy.value&&!loading.value&&!uncertain.value&&factory===factoryId.value&&id===form.workOrderId;if(!factory)return;const r=await warehouseOptions('work-orders',factory,undefined,valid,undefined,true);if(!valid())return;let changed=JSON.stringify(r.data)!==ordersBaseline;if(id){const detail=await orderDetail(id,valid,false,true);changed=changed||stamp(detail.data)!==orderBaseline}if(valid()&&changed){needsReload.value=true;error.value='业务资料已更新，请重新核对候选；当前输入已保留。'}}})
actionPermission.onChange(()=>{epoch++;dependency++;visible.value=false;busy.value=false;loading.value=false;uncertain.value=false;pendingRequest=undefined})
onBeforeRouteLeave(()=>{if(busy.value||uncertain.value)return false;visible.value=false});onBeforeRouteUpdate(()=>{if(busy.value||uncertain.value)return false;visible.value=false})
watch(visible,value=>{if(!value){epoch++;dependency++;busy.value=false}})
onBeforeUnmount(()=>{disposed=true;epoch++;dependency++})
defineExpose({open,isOpen:computed(()=>visible.value||loading.value)})
</script>